            py_exe = sys.executable
            # Remove the quotes if included
            if py_exe[0] == '"':
                py_exe = py_exe[1:-1]
            corrected_cmd[0] = py_exe

        if not corrected_cmd[0] and sys.executable and sys.executable.endswith('.exe'):
