def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent

    Parameters:
        classes (list): A list of base classes

    Returns:
        list: The ordered minimum equivalent of the input list of base classes
    """

    # Create a dictionary mapping each class to a list of its derived classes
    derived = {}
    for c in classes:
        for d in c.__bases__:
            if d not in derived:
                derived[d] = []
            derived[d].append(c)

    # Create a set of the known minimal base classes
    minimal = set(c.__bases__)

    # Iteratively add the minimal base classes that are derived from the
    # current minimal set of classes to the minimal set
    while True:
        new_minimal = set()
        for c in minimal:
            if c in derived:
                new_minimal.update(derived[c])
        if new_minimal == minimal:
            break
        minimal.update(new_minimal)

    return list(minimal)

